-- Explicações por artigo — Lei de Migração (Lei nº 13.445, de 2017). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Rascunhos em revisão. Publicação exige revisão explícita; reexecução preserva qualquer registro existente.

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei dispõe sobre os direitos e deveres do migrante e do visitante, regula a sua entrada e estada no País e estabelece princípios e diretrizes para as políticas públicas para o emigrante. Considera-se imigrante a pessoa nacional de outro país ou apátrida que trabalha ou reside e se estabelece temporária ou definitivamente no Brasil; emigrante, o brasileiro que se estabelece no exterior; residente fronteiriço, a pessoa nacional de país limítrofe ou apátrida que conserva residência habitual em município fronteiriço de país vizinho; visitante, a pessoa que vem ao Brasil para estadas de curta duração, sem pretensão de se estabelecer; e apátrida, a pessoa que não seja considerada nacional por nenhum Estado.', '["Direitos e deveres do migrante e do visitante.","Imigrante, emigrante, residente fronteiriço, visitante e apátrida.","Políticas públicas para o emigrante."]'::jsonb, '["ATUALIZAÇÃO: lei nova, que revogou o Estatuto do Estrangeiro (art. 124).","VISITANTE não pretende se estabelecer; IMIGRANTE sim."]'::jsonb, 'O turista é visitante; o trabalhador que se muda para o Brasil é imigrante.', '["Assertiva que ainda trata o estrangeiro como ''estrangeiro'' do antigo Estatuto erra: a Lei usa migrante e visitante."]'::jsonb, '[{"termo":"Apátrida","significado":"Pessoa que nenhum Estado considera como nacional."}]'::jsonb, '["Art. 124"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-1' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2c8f91e16535474e97bcc8780ddf9d568f63ea30112a11cfe9a8e370166542ed'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei não prejudica a aplicação de normas internas e internacionais específicas sobre refugiados, asilados, agentes e pessoal diplomático ou consular, funcionários de organização internacional e seus familiares.', '["Preserva as normas específicas sobre refugiados, asilados e diplomatas."]'::jsonb, '["Refugiados seguem a Lei nº 9.474, de 22 de julho de 1997."]'::jsonb, 'O refugiado continua sob o regime próprio de refúgio.', '["Assertiva que revoga as normas sobre refugiados erra: elas são preservadas."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
