insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A política migratória brasileira rege-se por princípios e diretrizes como a universalidade, indivisibilidade e interdependência dos direitos humanos; o repúdio e a prevenção à xenofobia, ao racismo e a qualquer discriminação; a não criminalização da migração; a promoção da entrada regular e da regularização documental; a acolhida humanitária; o direito à reunião familiar; a igualdade de tratamento; a inclusão social, laboral e produtiva; o acesso igualitário a serviços e benefícios sociais; o diálogo social e a participação cidadã do migrante; entre outros.', '["Direitos humanos e repúdio à xenofobia.","Não criminalização da migração.","Acolhida humanitária e reunião familiar.","Acesso igualitário a serviços sociais."]'::jsonb, '["Princípio da NÃO CRIMINALIZAÇÃO da migração."]'::jsonb, 'A política migratória prioriza acolhida e reunião familiar.', '["Assertiva que criminaliza a migração irregular como princípio da política erra: a Lei adota a não criminalização."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-3' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8e3edab9654d270233ac227b602872f08029b47624aac1c7de687c485c9be5f9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao migrante é garantida no território nacional, em condição de igualdade com os nacionais, a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, assegurados direitos e liberdades civis, sociais, culturais e econômicos; liberdade de circulação; reunião familiar; medidas de proteção a vítimas e testemunhas; envio de recursos ao exterior; reunião pacífica; associação, inclusive sindical; acesso a serviços de saúde, assistência e previdência social sem discriminação por nacionalidade ou condição migratória; amplo acesso à justiça e à assistência jurídica gratuita; direito à educação pública; e cumprimento das obrigações trabalhistas, entre outros.', '["Igualdade com os nacionais nos direitos fundamentais.","Liberdade de circulação, reunião familiar, associação e sindicalização.","Acesso à saúde, assistência, previdência e educação.","Acesso à justiça e assistência jurídica gratuita."]'::jsonb, '["Acesso à saúde e à educação SEM discriminação pela condição migratória."]'::jsonb, 'O migrante em situação irregular pode matricular o filho na escola pública.', '["Assertiva que nega o acesso à educação pública ao migrante irregular erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-4' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6ff43263f560db14168a405a378dd0c110584247bf2831baccaa2bff35a85c05'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São documentos de viagem o passaporte; o laissez-passer; a autorização de retorno; o salvo-conduto; a carteira de identidade de marítimo; a carteira de matrícula consular; o documento de identidade civil ou estrangeiro equivalente, quando admitido em tratado; o certificado de membro de tripulação de transporte aéreo; e outros reconhecidos em regulamento. Os documentos emitidos pelo Estado brasileiro são de propriedade da União, cabendo ao titular a posse direta e o uso regular.', '["Rol de documentos de viagem.","Os emitidos pelo Brasil pertencem à União.","Titular tem a posse direta e o uso regular."]'::jsonb, '["O passaporte brasileiro é de PROPRIEDADE DA UNIÃO."]'::jsonb, 'O passaporte é da União, e o titular tem apenas a posse direta.', '["Assertiva que atribui ao titular a propriedade do passaporte erra: é da União."]'::jsonb, '[{"termo":"Laissez-passer","significado":"Documento de viagem provisório para quem não tem passaporte."}]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-5' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'def99c9233efe082b09d9f57361bcfebf06bcb3318f59e43652e388147fade88'
