insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento disporá sobre requisitos de concessão de visto e sua simplificação, inclusive por reciprocidade; prazo de validade e forma de contagem; prazo máximo para a primeira entrada e a estada; hipóteses de dispensa recíproca ou unilateral de visto e de taxas; e solicitação e emissão de visto por meio eletrônico. A simplificação e a dispensa podem ser definidas por comunicação diplomática.', '["Matérias de regulamento: requisitos, prazos, dispensas e visto eletrônico.","Dispensa por comunicação diplomática."]'::jsonb, '["Dispensa por reciprocidade pode ser por comunicação diplomática."]'::jsonb, 'Um acordo de reciprocidade dispensa o visto entre dois países.', '["Assertiva que fixa na própria Lei todos os prazos do visto erra: eles vão para regulamento."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
