insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá ser denegado visto a quem se enquadrar em pelo menos um dos casos de impedimento dos incisos I, II, III, IV e IX do art. 45. A pessoa que tiver visto brasileiro denegado será impedida de ingressar no País enquanto permanecerem as condições que ensejaram a denegação.', '["Denegação por impedimentos do art. 45 (I, II, III, IV e IX).","Impedimento de ingresso enquanto persistirem as condições."]'::jsonb, '["Denegar é FACULDADE; não conceder (art. 10) é dever."]'::jsonb, 'A pessoa condenada por terrorismo pode ter o visto denegado.', '["Assertiva que torna obrigatória a denegação nas hipóteses do art. 45 erra: ''poderá''."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
