insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O registro consiste na identificação civil por dados biográficos e biométricos e é obrigatório a todo imigrante detentor de visto temporário ou de autorização de residência. Gera número único de identificação que garante o pleno exercício dos atos da vida civil, e o documento de identidade do imigrante é expedido com base nesse número. Enquanto não for expedida a identificação, o documento comprobatório do pedido garante o acesso aos direitos da Lei.', '["Registro com dados biográficos e biométricos.","Obrigatório ao detentor de visto temporário ou de autorização de residência.","Número único de identificação.","Comprovante do pedido garante direitos."]'::jsonb, '["Registro obrigatório para visto TEMPORÁRIO ou autorização de residência."]'::jsonb, 'O imigrante com visto temporário faz o registro e recebe o número único.', '["Assertiva que dispensa o registro do detentor de visto temporário erra."]'::jsonb, '[]'::jsonb, '["Art. 117"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-19' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7c391a2d9fc95d20e2095da5a3c16bd0172e4010b251c7e533f16ed092266a47'
