insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A identificação civil de solicitante de refúgio, de asilo, de reconhecimento de apatridia e de acolhimento humanitário poderá ser realizada com a apresentação dos documentos de que o imigrante dispuser.', '["Identificação com os documentos de que dispuser."]'::jsonb, '["Flexibilidade documental para pessoas vulneráveis."]'::jsonb, 'O solicitante de refúgio sem passaporte se identifica com os documentos que tem.', '["Assertiva que exige passaporte válido do solicitante de refúgio erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
