select u.id, u.content_sha256, 'Os documentos de identidade emitidos até a data de publicação da Lei continuarão válidos até sua total substituição.', '["Documentos antigos seguem válidos até a substituição."]'::jsonb, '["Norma de transição."]'::jsonb, 'O antigo RNE segue válido até ser substituído.', '["Assertiva que invalida de imediato os documentos antigos erra."]'::jsonb, '[]'::jsonb, '["Art. 117"]'::jsonb, 'under_review', 'claude'
