insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A identificação civil, o documento de identidade e as formas de gestão da base cadastral dos detentores de vistos diplomático, oficial e de cortesia atenderão a disposições específicas previstas em regulamento.', '["Regras específicas em regulamento para vistos especiais."]'::jsonb, '["Regime próprio por regulamento."]'::jsonb, 'O cadastro de diplomatas segue regras específicas.', '["Assertiva que sujeita os vistos especiais ao registro comum do art. 19 erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
