insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A fim de facilitar a sua livre circulação, poderá ser concedida ao residente fronteiriço, mediante requerimento, autorização para a realização de atos da vida civil. Condições específicas poderão ser estabelecidas em regulamento ou tratado.', '["Autorização ao residente fronteiriço para atos da vida civil."]'::jsonb, '["Concedida mediante requerimento."]'::jsonb, 'O morador de cidade vizinha na fronteira pode trabalhar e estudar do lado brasileiro.', '["Assertiva que concede a autorização automaticamente, sem requerimento, erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-23' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd9e2e5a78fce5d02dec606a7a5bf211139d7fabefd5ac6cc241016f49e9daebc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
