on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autorização indicará o Município fronteiriço no qual o residente estará autorizado a exercer os direitos a ele atribuídos. O residente fronteiriço detentor da autorização gozará das garantias e dos direitos do regime geral de migração, conforme regulamento. O espaço geográfico de abrangência e validade será especificado no documento.', '["Autorização indica o Município fronteiriço.","Garantias do regime geral de migração.","Abrangência geográfica no documento."]'::jsonb, '["Validade LIMITADA ao espaço geográfico indicado."]'::jsonb, 'A autorização vale só no Município fronteiriço indicado.', '["Assertiva que estende a autorização a todo o território nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-24' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '411690639d9240995b85690ba02f1c1ce462be69094b225ea6f30f904a2fa2c4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O documento de residente fronteiriço será cancelado, a qualquer tempo, se o titular tiver fraudado documento ou utilizado documento falso para obtê-lo; obtiver outra condição migratória; sofrer condenação penal; ou exercer direito fora dos limites previstos na autorização.', '["Cancelamento por fraude, nova condição migratória, condenação penal ou excesso."]'::jsonb, '["Cancelamento a QUALQUER tempo."]'::jsonb, 'O residente fronteiriço que fraudou documento tem a autorização cancelada.', '["Assertiva que exige trânsito em julgado e prazo para o cancelamento erra: pode ser a qualquer tempo."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-25' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1ddb8ef33912b19d50e1982769b84f88ed3cb1ba4f433a1438dbf0ff15dc5ea9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento disporá sobre instituto protetivo especial do apátrida, consolidado em processo simplificado de naturalização, iniciado tão logo seja reconhecida a apatridia. Durante o reconhecimento incidem as garantias da Convenção sobre o Estatuto dos Apátridas de 1954, da Convenção relativa ao Estatuto dos Refugiados e da Lei nº 9.474, de 22 de julho de 1997. Aplicam-se ao apátrida residente todos os direitos do migrante do art. 4º. O reconhecimento assegura os direitos da Convenção de 1954. O processo verifica se o solicitante é considerado nacional por algum Estado.', '["Processo simplificado de naturalização do apátrida.","Garantias das Convenções sobre apátridas e refugiados.","Direitos do migrante do art. 4º."]'::jsonb, '["Naturalização SIMPLIFICADA para o apátrida."]'::jsonb, 'Reconhecida a apatridia, inicia-se a naturalização simplificada.', '["Assertiva que nega ao apátrida os direitos do migrante erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-26' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a5d03c1ccb144dfff80d3dbecf101ffabf69c9115807ac187cd93f607e4a3b6d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O asilo político, que constitui ato discricionário do Estado, poderá ser diplomático ou territorial e será outorgado como instrumento de proteção à pessoa. Regulamento disporá sobre as condições para a concessão e a manutenção de asilo.', '["Asilo político é ato discricionário.","Pode ser diplomático ou territorial."]'::jsonb, '["Asilo é DISCRICIONÁRIO; refúgio tem critérios próprios."]'::jsonb, 'O Estado decide se concede o asilo territorial a um perseguido político.', '["Assertiva que considera o asilo ato vinculado erra: é discricionário."]'::jsonb, '[{"termo":"Asilo diplomático","significado":"Concedido em embaixada ou consulado."}]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-27' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '93210017c19a47566e88c34f9ce2df36fdd7fa2ae71b4150ad29f645fae43465'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se concederá asilo a quem tenha cometido crime de genocídio, crime contra a humanidade, crime de guerra ou crime de agressão, nos termos do Estatuto de Roma do Tribunal Penal Internacional, de 1998, promulgado pelo Decreto nº 4.388, de 25 de setembro de 2002.', '["Vedado o asilo a autores de genocídio, crimes contra a humanidade, de guerra e de agressão."]'::jsonb, '["Quatro crimes do Estatuto de Roma."]'::jsonb, 'Quem cometeu genocídio não pode receber asilo.', '["Assertiva que permite asilo a autor de crime de guerra erra."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
