insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A residência poderá ser autorizada, mediante registro, ao imigrante, ao residente fronteiriço ou ao visitante que tenha por finalidade pesquisa, ensino ou extensão; tratamento de saúde; acolhida humanitária; estudo; trabalho; férias-trabalho; atividade religiosa ou voluntariado; investimento; reunião familiar; ou que seja beneficiário de tratado de residência e livre circulação; detentor de oferta de trabalho; já tenha possuído a nacionalidade brasileira e não queira ou não possa readquiri-la; beneficiário de refúgio, asilo ou proteção ao apátrida; menor desacompanhado ou abandonado nas fronteiras ou no território; vítima de tráfico de pessoas, de trabalho escravo ou de violação de direito agravada pela condição migratória; ou pessoa em liberdade provisória ou cumprindo pena no Brasil; além de outras hipóteses do regulamento.', '["Autorização de residência mediante registro.","Finalidades como pesquisa, saúde, estudo, trabalho e reunião familiar.","Beneficiários de tratado, refúgio, asilo e apatridia.","Vítimas de tráfico de pessoas e trabalho escravo.","Pessoas em liberdade provisória ou cumprindo pena."]'::jsonb, '["A autorização alcança vítimas de tráfico de pessoas, trabalho escravo e violação agravada pela condição migratória.","Quem cumpre pena no Brasil também pode ter autorização de residência."]'::jsonb, 'A vítima de tráfico de pessoas pode obter autorização de residência.', '["Assertiva que exclui a vítima de tráfico de pessoas da autorização de residência erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-30' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9cc8cdc0dec4315e78c3a7cb7bf131c7a9db927de969cdd802bf16f26941d8c3'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
