insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os prazos e o procedimento da autorização de residência serão dispostos em regulamento. Será facilitada a autorização nas hipóteses de pesquisa, ensino ou extensão e de beneficiário de refúgio, asilo ou proteção ao apátrida, devendo a deliberação ocorrer em prazo não superior a 60 dias, a contar da solicitação. Nova autorização poderá ser concedida mediante requerimento, e o requerimento após o vencimento da anterior implica a sanção do inciso II do art. 109. O solicitante de refúgio, asilo ou proteção ao apátrida tem autorização provisória de residência até a resposta. Poderá ser concedida autorização independentemente da situação migratória.', '["Prazo de 60 dias para decidir nas hipóteses facilitadas.","Pedido após o vencimento gera sanção.","Autorização provisória para solicitante de refúgio.","Pode ser concedida independentemente da situação migratória."]'::jsonb, '["Prazo de 60 dias nas hipóteses facilitadas."]'::jsonb, 'O pesquisador estrangeiro tem a autorização decidida em até 60 dias.', '["Assertiva que fixa em 120 dias o prazo para pesquisa e refúgio erra: são 60."]'::jsonb, '[]'::jsonb, '["Art. 109"]'::jsonb, 'under_review', 'claude'
