insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá ser impedida de ingressar no País, após entrevista individual e mediante ato fundamentado, a pessoa anteriormente expulsa, enquanto os efeitos da expulsão vigorarem; condenada ou respondendo a processo por terrorismo, genocídio, crime contra a humanidade, de guerra ou de agressão; condenada ou respondendo a processo em outro país por crime doloso passível de extradição pela lei brasileira; com nome em lista de restrições por ordem judicial ou compromisso internacional; com documento de viagem inválido, vencido ou com rasura; sem documento de viagem ou identidade; cuja razão da viagem não condiga com o visto; que tenha fraudado documentação ou prestado informação falsa; ou que tenha praticado ato contrário aos princípios e objetivos da Constituição.', '["Impedimento após entrevista individual e ato fundamentado.","Expulso, terrorista, autor de crimes internacionais.","Condenado em outro país por crime extraditável.","Lista de restrições.","Documentos inválidos ou falsos.","Ato contrário à Constituição."]'::jsonb, '["Impedimento exige ENTREVISTA INDIVIDUAL e ATO FUNDAMENTADO."]'::jsonb, 'Quem apresenta passaporte vencido pode ter o ingresso impedido.', '["Assertiva que dispensa a entrevista individual e a fundamentação do impedimento erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
