select u.id, u.content_sha256, 'A aplicação do Capítulo sobre impedimento de ingresso observará a Lei de Refúgio (Lei nº 9.474, de 22 de julho de 1997) e as disposições legais, tratados e mecanismos de proteção aos apátridas ou de outras situações humanitárias.', '["Respeito à Lei de Refúgio e à proteção humanitária."]'::jsonb, '["Proteção humanitária prevalece."]'::jsonb, 'O solicitante de refúgio não é barrado na fronteira sem análise.', '["Assertiva que afasta a Lei de Refúgio do controle de ingresso erra."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
