insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A repatriação, a deportação e a expulsão serão feitas para o país de nacionalidade ou de procedência do migrante ou do visitante, ou para outro que o aceite, em observância aos tratados dos quais o Brasil seja parte.', '["Destino: país de nacionalidade, de procedência ou outro que aceite."]'::jsonb, '["Observância dos tratados."]'::jsonb, 'O deportado é enviado ao país de sua nacionalidade.', '["Assertiva que permite enviar o migrante a qualquer país, mesmo sem aceitação, erra."]'::jsonb, '[]'::jsonb, '["Arts. 49, 50 e 54"]'::jsonb, 'under_review', 'claude'
