insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos casos de deportação ou expulsão, o chefe da unidade da Polícia Federal poderá representar perante o juízo federal, respeitados, nos procedimentos judiciais, os direitos à ampla defesa e ao devido processo legal.', '["Representação do chefe da PF ao juízo federal.","Ampla defesa e devido processo legal."]'::jsonb, '["Juízo FEDERAL."]'::jsonb, 'A PF representa ao juiz federal para executar uma deportação.', '["Assertiva que atribui a representação ao juízo estadual erra: é o juízo federal."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
