insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A repatriação consiste em medida administrativa de devolução de pessoa em situação de impedimento ao país de procedência ou de nacionalidade. Será feita imediata comunicação do ato à empresa transportadora e à autoridade consular. A Defensoria Pública da União será notificada, preferencialmente por via eletrônica, quando a repatriação imediata não seja possível. Condições específicas podem ser definidas por regulamento ou tratado. Não será aplicada repatriação a pessoa em situação de refúgio ou apatridia, a menor de 18 anos desacompanhado ou separado da família (salvo se favorável à garantia de seus direitos), a quem necessite de acolhimento humanitário, nem devolução a país ou região que possa apresentar risco à vida, à integridade pessoal ou à liberdade.', '["Devolução administrativa de quem está impedido.","Comunicação à transportadora e ao consulado.","Notificação da Defensoria Pública da União.","Vedada a repatriação de refugiados, apátridas e menores desacompanhados, salvo exceção.","Vedada a devolução a país com risco à vida."]'::jsonb, '["NÃO repatria refugiado, apátrida ou menor desacompanhado (salvo exceção).","Vedada a devolução a país com risco à vida (non-refoulement)."]'::jsonb, 'O impedido na fronteira é devolvido ao país de procedência, exceto se for refugiado.', '["Assertiva que permite repatriar refugiado erra: é vedado."]'::jsonb, '[{"termo":"Non-refoulement","significado":"Proibição de devolver a pessoa a local onde corra risco de vida ou perseguição."}]'::jsonb, '["Art. 62"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-49' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a1230826a6c2c01bc46831abbe45212caaeeb868c811f3052af185164fc883b7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A deportação é medida decorrente de procedimento administrativo que consiste na retirada compulsória de pessoa em situação migratória irregular em território nacional. Será precedida de notificação pessoal ao deportando, com as irregularidades verificadas e prazo para regularização não inferior a 60 dias, prorrogável por igual período mediante despacho fundamentado. A notificação não impede a livre circulação. Vencido o prazo sem regularização, a deportação poderá ser executada. A deportação não exclui direitos adquiridos. A saída voluntária equivale ao cumprimento da notificação. O prazo poderá ser reduzido nos casos do inciso IX do art. 45.', '["Retirada compulsória de quem está em situação irregular.","Notificação pessoal com prazo não inferior a 60 dias.","Prorrogação por igual período.","Saída voluntária equivale ao cumprimento."]'::jsonb, '["Prazo de regularização: NÃO INFERIOR a 60 dias, prorrogável por igual período."]'::jsonb, 'O imigrante irregular é notificado e tem 60 dias para regularizar a situação.', '["Assertiva que fixa em 10 dias o prazo de regularização da deportação erra: é de no mínimo 60."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-50' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '176eb3e621de013687e856ceefb3e743409fef43a45067b265541093010d3139'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
