insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os procedimentos conducentes à deportação devem respeitar o contraditório e a ampla defesa e a garantia de recurso com efeito suspensivo. A Defensoria Pública da União deverá ser notificada, preferencialmente por meio eletrônico, para assistir o deportando. A ausência de manifestação da Defensoria, desde que prévia e devidamente notificada, não impedirá a efetivação da deportação.', '["Contraditório, ampla defesa e recurso com efeito suspensivo.","Notificação da Defensoria Pública da União.","Silêncio da Defensoria não impede a deportação."]'::jsonb, '["Recurso com EFEITO SUSPENSIVO."]'::jsonb, 'O deportando recorre, e o recurso suspende a deportação.', '["Assertiva que nega efeito suspensivo ao recurso contra a deportação erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-51' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9edda7acb2006b9eeaf4b391bf19364f594e0fc7270a141dc90405939c9e381a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
