insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em se tratando de apátrida, o procedimento de deportação dependerá de prévia autorização da autoridade competente.', '["Deportação de apátrida exige autorização prévia."]'::jsonb, '["Proteção reforçada ao apátrida."]'::jsonb, 'A deportação de um apátrida depende de autorização prévia.', '["Assertiva que dispensa autorização para deportar apátrida erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-52' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '12fdd79281e4ed2515c97479cb5a9e44a55e510e36bc614f314e5051c9cdfb92'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
