insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se procederá à deportação se a medida configurar extradição não admitida pela legislação brasileira.', '["Vedada a deportação disfarçada de extradição."]'::jsonb, '["Evita extradição disfarçada."]'::jsonb, 'Não se pode deportar para entregar o estrangeiro a país que pede sua extradição, se esta for vedada.', '["Assertiva que permite deportação equivalente a extradição proibida erra."]'::jsonb, '[]'::jsonb, '["Art. 82"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-53' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f2de4f5df67774b2e2dd10ab894a477fb9cbb857f58825693f30e045f369610b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A expulsão consiste em medida administrativa de retirada compulsória de migrante ou visitante do território nacional, conjugada com o impedimento de reingresso por prazo determinado. Pode dar causa à expulsão a condenação com trânsito em julgado por crime de genocídio, contra a humanidade, de guerra ou de agressão, ou por crime comum doloso passível de pena privativa de liberdade, consideradas a gravidade e as possibilidades de ressocialização. A autoridade competente resolve sobre a expulsão, a duração do impedimento e a suspensão ou revogação dos efeitos. O processamento da expulsão não prejudica progressão de regime, cumprimento da pena, suspensão condicional do processo, comutação, pena alternativa, indulto ou anistia concedidos em igualdade com o brasileiro.', '["Retirada compulsória com impedimento de reingresso por prazo determinado.","Causas: condenação transitada em julgado por crimes graves.","Não prejudica benefícios penais em igualdade com o nacional."]'::jsonb, '["Expulsão exige condenação com TRÂNSITO EM JULGADO."]'::jsonb, 'O estrangeiro condenado definitivamente por crime doloso grave pode ser expulso.', '["Assertiva que permite expulsão por mera acusação, sem condenação, erra."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-54' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '714f13f65c33b794b3e1d88326c080ac366cf8fe7f7b5ae3bbfb202fa76c0499'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se procederá à expulsão quando a medida configurar extradição inadmitida pela legislação brasileira, ou quando o expulsando tiver filho brasileiro sob sua guarda ou dependência econômica ou socioafetiva, ou pessoa brasileira sob sua tutela; tiver cônjuge ou companheiro residente no Brasil, sem discriminação; tiver ingressado no Brasil até os 12 anos de idade, residindo desde então no País; ou for pessoa com mais de 70 anos que resida no País há mais de 10 anos, considerados a gravidade e o fundamento da expulsão.', '["Extradição inadmitida.","Filho brasileiro sob guarda ou dependência.","Cônjuge ou companheiro residente no Brasil.","Ingresso até os 12 anos de idade.","Mais de 70 anos com mais de 10 anos de residência."]'::jsonb, '["Entrada até os 12 anos de idade.","Mais de 70 anos e mais de 10 anos de residência."]'::jsonb, 'O estrangeiro que tem filho brasileiro sob sua guarda não pode ser expulso.', '["Assertiva que permite expulsar quem entrou no Brasil aos 8 anos erra: a vedação vale para quem ingressou até os 12 anos."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-55' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60b6c4035da68e6ba5148edceee87b241f91ec41652114441f8d5916d26b7f94'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
