insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento definirá procedimentos para apresentação e processamento de pedidos de suspensão e de revogação dos efeitos das medidas de expulsão e de impedimento de ingresso e permanência em território nacional.', '["Procedimentos de suspensão e revogação das medidas por regulamento."]'::jsonb, '["Matéria de regulamento."]'::jsonb, 'O expulso pode pedir a revogação dos efeitos da medida, nos termos do regulamento.', '["Assertiva que torna a expulsão irrevogável erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
