insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No processo de expulsão serão garantidos o contraditório e a ampla defesa. A Defensoria Pública da União será notificada da instauração do processo, se não houver defensor constituído. Caberá pedido de reconsideração da decisão sobre a expulsão no prazo de 10 dias, a contar da notificação pessoal do expulsando.', '["Contraditório e ampla defesa.","Notificação da Defensoria Pública da União.","Reconsideração em 10 dias."]'::jsonb, '["Reconsideração em 10 dias."]'::jsonb, 'O expulsando pede reconsideração em dez dias.', '["Assertiva que fixa em 30 dias o prazo de reconsideração erra: são 10."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
