insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O filho de pai ou de mãe brasileiro nascido no exterior e que não tenha sido registrado em repartição consular poderá, a qualquer tempo, promover ação de opção de nacionalidade. O órgão de registro deve informar periodicamente à autoridade competente os dados relativos à opção de nacionalidade, conforme regulamento.', '["Ação de opção de nacionalidade a qualquer tempo.","Para filho de brasileiro nascido no exterior e não registrado em repartição consular."]'::jsonb, '["Opção a QUALQUER tempo."]'::jsonb, 'O filho de brasileira nascido no exterior pode optar pela nacionalidade quando quiser.', '["Assertiva que fixa prazo para a opção de nacionalidade erra: pode ser a qualquer tempo."]'::jsonb, '[]'::jsonb, '["Constituição, art. 12"]'::jsonb, 'under_review', 'claude'
