insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo de residência da naturalização ordinária será reduzido para, no mínimo, 1 ano se o naturalizando tiver filho brasileiro; tiver cônjuge ou companheiro brasileiro e não estiver dele separado legalmente ou de fato; houver prestado ou puder prestar serviço relevante ao Brasil; ou recomendar-se por sua capacidade profissional, científica ou artística. As condições dos incisos V e VI serão avaliadas na forma do regulamento.', '["Redução do prazo para 1 ano.","Filho brasileiro.","Cônjuge ou companheiro brasileiro.","Serviço relevante ao Brasil.","Capacidade profissional, científica ou artística."]'::jsonb, '["Redução para 1 ano."]'::jsonb, 'Quem tem filho brasileiro pode se naturalizar com 1 ano de residência.', '["Assertiva que reduz o prazo a 2 anos nessas hipóteses erra: é 1 ano."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
