select u.id, u.content_sha256, 'Em caso de ameaça à paz social e à ordem pública por grave ou iminente instabilidade institucional ou de calamidade de grande proporção na natureza, deverá ser prestada especial assistência ao emigrante pelas representações brasileiras no exterior.', '["Assistência especial ao emigrante em crises."]'::jsonb, '["Dever de assistência em instabilidade ou calamidade."]'::jsonb, 'O consulado auxilia os brasileiros durante uma catástrofe natural no exterior.', '["Assertiva que torna facultativa a assistência especial em calamidades erra: ''deverá''."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
