insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tripulante brasileiro contratado por embarcação ou armadora estrangeira, de cabotagem ou a longo curso e com sede ou filial no Brasil, que explore economicamente o mar territorial e a costa brasileira, terá direito a seguro a cargo do contratante, válido para todo o período da contratação, contra acidente de trabalho, invalidez total ou parcial e morte, sem prejuízo de benefícios de apólice mais favorável vigente no exterior.', '["Seguro a cargo do contratante.","Cobre acidente de trabalho, invalidez e morte.","Sem prejuízo de apólice mais favorável no exterior."]'::jsonb, '["O seguro é custeado pelo CONTRATANTE."]'::jsonb, 'O marinheiro brasileiro em navio estrangeiro tem seguro pago pela armadora.', '["Assertiva que atribui ao tripulante o custeio do seguro erra."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
