insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se concederá a extradição quando o indivíduo for brasileiro nato; o fato não for crime no Brasil ou no Estado requerente; o Brasil for competente para julgar o crime; a lei brasileira impuser ao crime pena de prisão inferior a 2 anos; o extraditando estiver respondendo a processo ou já tiver sido condenado ou absolvido no Brasil pelo mesmo fato; a punibilidade estiver extinta pela prescrição; o fato constituir crime político ou de opinião; o extraditando tiver de responder, no Estado requerente, perante tribunal de exceção; ou for beneficiário de refúgio ou de asilo territorial. A vedação do crime político não impede a extradição quando o fato constituir principalmente infração à lei penal comum. Cabe à autoridade judiciária apreciar o caráter da infração.', '["Brasileiro nato não é extraditado.","Dupla incriminação.","Pena de prisão inferior a 2 anos.","Crime político ou de opinião.","Tribunal de exceção.","Refugiado ou asilado."]'::jsonb, '["Pena de prisão INFERIOR a 2 anos impede a extradição.","Brasileiro NATO não é extraditado (o naturalizado pode ser, em hipóteses constitucionais)."]'::jsonb, 'O brasileiro nato não pode ser extraditado.', '["Assertiva que permite extraditar brasileiro nato erra."]'::jsonb, '[{"termo":"Dupla incriminação","significado":"O fato deve ser crime nos dois países."}]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-82' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5f8d44e53dcc1ea74e65d7a5ac44493436b9eae853a51d2f7eca297f9585b9c9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São condições para concessão da extradição ter sido o crime cometido no território do Estado requerente ou serem aplicáveis ao extraditando as leis penais desse Estado; e estar o extraditando respondendo a processo investigatório ou a processo penal ou ter sido condenado pelas autoridades judiciárias do Estado requerente a pena privativa de liberdade.', '["Crime no território do Estado requerente ou sujeito às suas leis penais.","Processo investigatório, processo penal ou condenação a pena privativa de liberdade."]'::jsonb, '["Admite processo investigatório."]'::jsonb, 'O país requerente já iniciou o processo contra o extraditando.', '["Assertiva que exige sempre condenação definitiva erra: basta processo investigatório ou penal."]'::jsonb, '[]'::jsonb, '["Art. 82"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-83' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '23d58110b70d28a370554b2799bada0ca20cb327cd4ba352ebdf9f4296fb800e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de urgência, o Estado interessado poderá, previamente ou junto com o pedido de extradição, requerer prisão cautelar, por via diplomática ou autoridade central, para assegurar a executoriedade da extradição, que, após exame dos pressupostos formais, deverá ser representada à autoridade judicial competente, ouvido previamente o Ministério Público Federal. O pedido de prisão cautelar deverá conter informação sobre o crime e ser fundamentado, podendo ser apresentado por correio, fax, mensagem eletrônica ou outro meio por escrito, e transmitido por canal com a Interpol, com documentação da ordem de prisão estrangeira e, na ausência de tratado, com promessa de reciprocidade.', '["Prisão cautelar em caso de urgência.","Ouvido previamente o Ministério Público Federal.","Pedido por qualquer meio escrito, inclusive pela Interpol."]'::jsonb, '["Prisão cautelar precede ou acompanha o pedido de extradição."]'::jsonb, 'Um país pede a prisão cautelar do foragido pela Interpol.', '["Assertiva que dispensa a oitiva do MPF no pedido de prisão cautelar erra."]'::jsonb, '[{"termo":"Interpol","significado":"Organização Internacional de Polícia Criminal."}]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-84' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f1d49c4bfd9b6184e2d2a5492c9af296e47056d3997caa1bef422c4ec4169839'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando mais de um Estado requerer a extradição da mesma pessoa, pelo mesmo fato, terá preferência o pedido daquele em cujo território a infração foi cometida. Em crimes diversos, terá preferência o Estado em cujo território tenha sido cometido o crime mais grave, segundo a lei brasileira; o Estado que primeiro pediu, se a gravidade for idêntica; e o Estado de origem ou, em sua falta, o domiciliar, se os pedidos forem simultâneos. Nos casos não previstos, o Executivo decide, priorizando o Estado que mantiver tratado com o Brasil, e prevalecem as normas do tratado.', '["Preferência do Estado onde ocorreu a infração.","Crimes diversos: o mais grave; depois o primeiro pedido; depois o Estado de origem ou domiciliar.","Tratado prevalece."]'::jsonb, '["Ordem de preferência entre pedidos concorrentes."]'::jsonb, 'Entre dois pedidos, prevalece o do país onde o crime ocorreu.', '["Assertiva que dá preferência ao primeiro pedido independentemente do local do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-85' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e8920d88f0d0d7eb0145788ea324cd68283fa8abd21c04ae7c426b3cfbd8b81b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Supremo Tribunal Federal, ouvido o Ministério Público, poderá autorizar prisão albergue ou domiciliar ou determinar que o extraditando responda ao processo de extradição em liberdade, com retenção do documento de viagem ou outras medidas cautelares, até o julgamento ou a entrega, considerando a situação administrativa migratória, os antecedentes e as circunstâncias do caso.', '["STF pode autorizar prisão domiciliar ou liberdade com cautelares."]'::jsonb, '["Competência do STF."]'::jsonb, 'O STF permite que o extraditando aguarde em prisão domiciliar.', '["Assertiva que obriga a prisão em regime fechado durante todo o processo de extradição erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-86' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '41fe379c355a5811e479664ce81466e890889ff806b146ae8b23182f84eb3585'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O extraditando poderá entregar-se voluntariamente ao Estado requerente, desde que o declare expressamente, esteja assistido por advogado e seja advertido de que tem direito ao processo judicial de extradição e à proteção que tal direito encerra, caso em que o pedido será decidido pelo Supremo Tribunal Federal.', '["Entrega voluntária com declaração expressa e advogado.","Pedido decidido pelo STF."]'::jsonb, '["Mesmo na entrega voluntária, o STF decide."]'::jsonb, 'O extraditando, assistido por advogado, concorda com a entrega ao país requerente.', '["Assertiva que dispensa advogado na entrega voluntária erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-87' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b18207b05cb18ec7b35ca9d19959e3a2cab54502be4cd2c854ffc809be9d7857'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo pedido que possa originar processo de extradição em face de Estado estrangeiro deverá ser encaminhado ao órgão competente do Poder Executivo diretamente pelo órgão do Poder Judiciário responsável pela decisão ou pelo processo penal. Compete ao Executivo orientar, informar e avaliar os elementos formais de admissibilidade. Compete aos órgãos do sistema de Justiça apresentar os documentos, manifestações e traduções oficiais. O pedido será instruído com cópia da sentença ou decisão penal, indicações sobre o fato e a identidade, e cópia dos textos legais. O encaminhamento ao Executivo confere autenticidade aos documentos.', '["Pedido de extradição ativa vai do Judiciário ao Executivo.","Executivo avalia a admissibilidade formal.","Instrução com a decisão penal e textos legais.","Encaminhamento confere autenticidade."]'::jsonb, '["Extradição ATIVA: o Brasil pede a entrega de alguém."]'::jsonb, 'O juiz brasileiro encaminha ao Executivo o pedido de extradição do foragido no exterior.', '["Assertiva que manda o juiz enviar o pedido diretamente ao Estado estrangeiro erra: vai ao Poder Executivo."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-88' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cfe19117f36083a526c349b3c1b32f6efded5c83b87eaaea188f4a6936404f9d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O pedido de extradição originado de Estado estrangeiro será recebido pelo órgão competente do Poder Executivo e, após exame dos pressupostos formais de admissibilidade, encaminhado à autoridade judiciária competente. Não preenchidos os pressupostos, o pedido será arquivado mediante decisão fundamentada, sem prejuízo de renovação, devidamente instruído, uma vez superado o óbice.', '["Executivo recebe e examina os pressupostos formais.","Encaminhamento ao Judiciário.","Arquivamento fundamentado, com possibilidade de renovar."]'::jsonb, '["Extradição PASSIVA: outro país pede ao Brasil."]'::jsonb, 'O Executivo examina o pedido do país estrangeiro antes de enviá-lo ao STF.', '["Assertiva que torna definitivo o arquivamento do pedido erra: pode ser renovado."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-89' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '048909e5dc906a2c6a10731e03933b638f540d6ec8324f865fa216b3d9989d12'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

