select u.id, u.content_sha256, 'Nenhuma extradição será concedida sem prévio pronunciamento do Supremo Tribunal Federal sobre sua legalidade e procedência, não cabendo recurso da decisão.', '["Prévio pronunciamento do STF.","Sem recurso."]'::jsonb, '["O STF controla a LEGALIDADE e a PROCEDÊNCIA."]'::jsonb, 'Só com a decisão do STF a extradição é concedida.', '["Assertiva que permite a extradição sem decisão do STF erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-90' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e5a8cde20eb6c913996c366192409df2c8d7537bf7170fbc491a037bc51f90be'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao receber o pedido, o relator designará dia e hora para o interrogatório do extraditando e, conforme o caso, nomear-lhe-á curador ou advogado, se não o tiver. A defesa, no prazo de 10 dias contado do interrogatório, versará sobre a identidade da pessoa reclamada, defeito de forma de documento ou ilegalidade da extradição. Não estando o processo instruído, o Tribunal poderá converter o julgamento em diligência, e o Ministério Público Federal terá prazo improrrogável de 60 dias para supri-la, contado da notificação à missão diplomática do Estado requerente.', '["Interrogatório do extraditando.","Defesa em 10 dias: identidade, defeito de forma e ilegalidade.","Diligência com prazo improrrogável de 60 dias."]'::jsonb, '["A defesa só discute IDENTIDADE, FORMA e ILEGALIDADE (não o mérito)."]'::jsonb, 'O extraditando apresenta defesa em 10 dias sobre sua identidade e a forma dos documentos.', '["Assertiva que permite discutir o mérito da acusação na defesa da extradição erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-91' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '28a75799a83efa15ae52af2b78c50590f2fd30961abfc1154bd1e04eb259653b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Julgada procedente a extradição e autorizada a entrega pelo órgão competente do Poder Executivo, o ato será comunicado por via diplomática ao Estado requerente, que, no prazo de 60 dias da comunicação, deverá retirar o extraditando do território nacional.', '["Prazo de 60 dias para o Estado requerente retirar o extraditando."]'::jsonb, '["Prazo de 60 dias."]'::jsonb, 'O país requerente tem 60 dias para buscar o extraditando.', '["Assertiva que fixa em 30 dias o prazo de retirada erra: são 60."]'::jsonb, '[]'::jsonb, '["Art. 93"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-92' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8181dddd3a4f584912ef7ee62acf57b082255e6cf24430597a6247eb7b4f3074'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o Estado requerente não retirar o extraditando do território nacional no prazo previsto no art. 92, será ele posto em liberdade, sem prejuízo de outras medidas aplicáveis.', '["Soltura se o Estado requerente não retirar o extraditando no prazo."]'::jsonb, '["Consequência: liberdade."]'::jsonb, 'Passados os 60 dias sem retirada, o extraditando é solto.', '["Assertiva que mantém a prisão indefinidamente se o Estado não retira o extraditando erra."]'::jsonb, '[]'::jsonb, '["Art. 92"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-93' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6d4e41a3dd33214a0060823987645743d91ed9d28d70e4368ec25d161b87fc63'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
