insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Negada a extradição em fase judicial, não se admitirá novo pedido baseado no mesmo fato.', '["Negada a extradição, não se admite novo pedido pelo mesmo fato."]'::jsonb, '["Coisa julgada na extradição."]'::jsonb, 'Se o STF nega a extradição, o mesmo fato não pode embasar novo pedido.', '["Assertiva que permite renovar o pedido após a negativa judicial erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-94' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f0c4d5cb2084f560047f45194e29bffe547c862ab1c34a55c8a85cb4baaa13bd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o extraditando estiver sendo processado ou tiver sido condenado, no Brasil, por crime punível com pena privativa de liberdade, a extradição será executada somente depois da conclusão do processo ou do cumprimento da pena, ressalvadas a liberação antecipada pelo Judiciário e a transferência da pessoa condenada. A entrega será igualmente adiada se puser em risco sua vida em virtude de enfermidade grave comprovada por laudo oficial. Se for por infração de menor potencial ofensivo, a entrega poderá ser imediata.', '["Extradição após o processo ou a pena no Brasil.","Adiamento por enfermidade grave.","Infração de menor potencial ofensivo: entrega imediata."]'::jsonb, '["Primeiro responde no Brasil; depois é extraditado (salvo menor potencial ofensivo)."]'::jsonb, 'O extraditando que cumpre pena no Brasil só é entregue depois de cumpri-la.', '["Assertiva que manda extraditar imediatamente quem cumpre pena grave no Brasil erra."]'::jsonb, '[]'::jsonb, '["Art. 96"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-95' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '891cb3723617f106f40109cb69de62afe920cc150ec43f9e6c0ae329bf267778'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não será efetivada a entrega do extraditando sem que o Estado requerente assuma o compromisso de não submetê-lo a prisão ou processo por fato anterior ao pedido; computar o tempo de prisão imposto no Brasil por força da extradição; comutar a pena corporal, perpétua ou de morte em pena privativa de liberdade, respeitado o limite máximo de cumprimento de 30 anos; não entregá-lo a outro Estado sem consentimento do Brasil; não considerar motivo político para agravar a pena; e não submetê-lo a tortura ou a outros tratamentos ou penas cruéis, desumanos ou degradantes.', '["Princípio da especialidade.","Detração do tempo de prisão no Brasil.","Comutação da pena de morte ou perpétua, com limite de 30 anos.","Proibição de reextradição sem consentimento.","Proibição de tortura."]'::jsonb, '["Pena de morte e prisão perpétua devem ser comutadas, com limite máximo de 30 anos."]'::jsonb, 'O país requerente promete não aplicar pena de morte e limitar a prisão a 30 anos.', '["Assertiva que permite a extradição sem compromisso de comutar a pena de morte erra."]'::jsonb, '[{"termo":"Especialidade","significado":"O extraditado só responde pelo fato objeto do pedido."}]'::jsonb, '["Art. 82"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-96' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b1756c595059a68288de8b8ef444330debbd86cbcdc1dbaff778a7606c476360'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A entrega do extraditando, de acordo com as leis brasileiras e respeitado o direito de terceiro, será feita com os objetos e instrumentos do crime encontrados em seu poder. Os objetos e instrumentos poderão ser entregues independentemente da entrega do extraditando.', '["Entrega com os objetos e instrumentos do crime.","Possível entregá-los separadamente."]'::jsonb, '["Respeita direito de terceiro."]'::jsonb, 'A arma do crime é entregue junto com o extraditando.', '["Assertiva que impede a entrega dos objetos do crime sem o extraditando erra."]'::jsonb, '[]'::jsonb, '["Art. 96"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-97' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'dadb7146319df4661d8c09b84e723dc4bae5c3d8ce98aab6b96beaffb856040e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O extraditando que, depois de entregue ao Estado requerente, escapar à ação da Justiça e homiziar-se no Brasil, ou por ele transitar, será detido mediante pedido feito diretamente por via diplomática ou pela Interpol e novamente entregue, sem outras formalidades.', '["Nova entrega, sem outras formalidades, se o extraditado fugir e vier ao Brasil."]'::jsonb, '["Sem novo processo de extradição."]'::jsonb, 'O foragido que volta ao Brasil é detido a pedido da Interpol e devolvido.', '["Assertiva que exige novo processo de extradição para a nova entrega erra: é sem outras formalidades."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-98' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '64ac87011d828f5bfcbb43d8dc27159edb8dd39e5039f87d8d4b47990b220891'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo motivo de ordem pública, poderá ser permitido, pelo órgão competente do Poder Executivo, o trânsito no território nacional de pessoa extraditada por Estado estrangeiro, bem como o da respectiva guarda, mediante apresentação de documento comprobatório de concessão da medida.', '["Trânsito no Brasil de pessoa extraditada por outro Estado, salvo motivo de ordem pública."]'::jsonb, '["Autorização do Executivo."]'::jsonb, 'O extraditado passa pelo Brasil, escoltado, a caminho do país requerente.', '["Assertiva que proíbe o trânsito de extraditados pelo Brasil erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-99' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ffc1892f32d45b0ab5f97f9068534e9a3e3c9c2a01219cd66c22dc8a520f663b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas hipóteses em que couber solicitação de extradição executória, a autoridade competente poderá solicitar ou autorizar a transferência de execução da pena, observado o princípio do non bis in idem. A transferência será possível quando o condenado em território estrangeiro for nacional ou tiver residência habitual ou vínculo pessoal no Brasil; a sentença tiver transitado em julgado; a duração da condenação a cumprir for de pelo menos 1 ano na data do pedido; o fato constituir infração penal perante a lei de ambas as partes; e houver tratado ou promessa de reciprocidade.', '["Transferência de execução da pena.","Nacional ou residente no Brasil.","Sentença transitada em julgado.","Pelo menos 1 ano a cumprir.","Dupla incriminação e tratado ou reciprocidade."]'::jsonb, '["Pelo menos 1 ano de pena a cumprir."]'::jsonb, 'O brasileiro condenado no exterior pode cumprir a pena no Brasil.', '["Assertiva que dispensa o trânsito em julgado da sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-100' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fbf66af256336b59f3e3730440aef9d591bbc5d810b1ab149874a0d38c2f6a80'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O pedido de transferência de execução da pena de Estado estrangeiro será requerido por via diplomática ou por autoridades centrais, recebido pelo órgão competente do Executivo e, após exame dos pressupostos formais, encaminhado ao Superior Tribunal de Justiça para decisão quanto à homologação. Não preenchidos os pressupostos, será arquivado mediante decisão fundamentada, sem prejuízo de renovação.', '["Pedido por via diplomática ou autoridade central.","Homologação pelo Superior Tribunal de Justiça."]'::jsonb, '["Quem homologa é o STJ (na extradição é o STF)."]'::jsonb, 'O STJ homologa a transferência da execução da pena.', '["Assertiva que atribui ao STF a homologação da transferência da execução da pena erra: é do STJ."]'::jsonb, '[]'::jsonb, '["Art. 100"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-101' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd145814f3131329c17ed567b7bf20d002c56794db80f5902d589f37b4d329427'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A forma do pedido de transferência de execução da pena e seu processamento serão definidos em regulamento. Nos casos previstos nesta Seção, a execução penal será de competência da Justiça Federal.', '["Forma e processamento em regulamento.","Execução penal na Justiça Federal."]'::jsonb, '["Competência da JUSTIÇA FEDERAL para a execução."]'::jsonb, 'A pena transferida é executada pela Justiça Federal.', '["Assertiva que atribui a execução à Justiça Estadual erra: é da Justiça Federal."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-102' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7c3471e8efacdf2fb736d34baef09cea620717ef10d4b4ba4322d4105c8c69c3'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A transferência de pessoa condenada poderá ser concedida quando o pedido se fundamentar em tratado ou houver promessa de reciprocidade. O condenado no território nacional poderá ser transferido para seu país de nacionalidade ou país em que tiver residência habitual ou vínculo pessoal, desde que expresse interesse, para cumprir a pena imposta pelo Brasil por sentença transitada em julgado. A transferência pode ser concedida com medida de impedimento de reingresso no território nacional.', '["Transferência com base em tratado ou reciprocidade.","Condenado no Brasil cumpre pena em seu país, se tiver interesse.","Pode haver impedimento de reingresso."]'::jsonb, '["Exige INTERESSE do condenado."]'::jsonb, 'O estrangeiro condenado no Brasil pede para cumprir a pena em seu país.', '["Assertiva que dispensa o interesse do condenado na transferência erra."]'::jsonb, '[]'::jsonb, '["Art. 104"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-103' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4be6ff6a2618596125355034d56957a5e4e7e2c4687c3336c0322ac544aee0b4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
