and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A forma do pedido de transferência de pessoa condenada e seu processamento serão definidos em regulamento. Nos casos previstos nesta Seção, a execução penal será de competência da Justiça Federal. Não se procederá à transferência quando inadmitida a extradição.', '["Forma em regulamento.","Execução na Justiça Federal.","Sem transferência se a extradição for inadmitida."]'::jsonb, '["Extradição inadmitida impede a transferência."]'::jsonb, 'Se a extradição é vedada, a transferência também é.', '["Assertiva que permite a transferência mesmo quando a extradição é inadmitida erra."]'::jsonb, '[]'::jsonb, '["Art. 82"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-105' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bf318220a28d98208a709877c8292b0d81b7180c6ee1125e42888c8bbbd2251e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento disporá sobre o procedimento de apuração das infrações administrativas e seu processamento e sobre a fixação e a atualização das multas, em observância ao disposto na Lei.', '["Procedimento e multas por regulamento."]'::jsonb, '["Matéria regulamentar."]'::jsonb, 'O regulamento detalha como se apura a infração migratória.', '["Assertiva que fixa todos os procedimentos na própria Lei erra."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-106' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4ecd53a2d8bc7335e9034fb8703c73bdc081a1c75bef940ec8ba30c2cc364e5c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
