on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As infrações administrativas serão apuradas em processo administrativo próprio, assegurados o contraditório e a ampla defesa. O cometimento simultâneo de duas ou mais infrações importará cumulação das sanções, respeitados os limites do art. 108. A multa por dia de atraso ou por excesso de permanência poderá ser convertida em redução equivalente do período de autorização de estada para o visto de visita, em caso de nova entrada.', '["Processo administrativo próprio com contraditório.","Cumulação de sanções.","Multa por excesso de permanência pode ser convertida em redução da estada."]'::jsonb, '["Multa convertida em REDUÇÃO de estada na próxima visita."]'::jsonb, 'A multa por excesso de permanência vira redução do prazo da próxima visita.', '["Assertiva que impede a conversão da multa por excesso de permanência erra."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-107' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0e7252af46520339eca3db7f99259549c82c77e1c30fd1480ad7e371c1075c67'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O valor das multas considerará as hipóteses individualizadas na Lei; a condição econômica do infrator, a reincidência e a gravidade da infração; a atualização periódica conforme regulamento; o valor mínimo individualizável de R$ 100,00; o valor de R$ 100,00 a R$ 10.000,00 para pessoa física; e o valor de R$ 1.000,00 a R$ 1.000.000,00 para pessoa jurídica, por ato infracional.', '["Critérios: hipóteses legais, condição econômica, reincidência e gravidade.","Pessoa física: R$ 100,00 a R$ 10.000,00.","Pessoa jurídica: R$ 1.000,00 a R$ 1.000.000,00."]'::jsonb, '["Limites distintos para pessoa física e jurídica."]'::jsonb, 'A empresa transportadora pode ser multada em até R$ 1.000.000,00 por infração.', '["Assertiva que fixa o teto da multa da pessoa física em R$ 1.000.000,00 erra: é R$ 10.000,00."]'::jsonb, '[]'::jsonb, '["Art. 109"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-108' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e4e0ed57ae363bd4f7943929e765864bc394aa56968edf17f5a0e3dd0ec3d5e9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui infração, com as sanções indicadas: entrar em território nacional sem estar autorizado (deportação, se não sair ou não regularizar); permanecer após esgotado o prazo legal (multa por dia de excesso e deportação); deixar de se registrar em 90 dias do ingresso, quando obrigatória a identificação civil (multa); deixar o imigrante de se registrar para autorização de residência em 30 dias, quando orientado (multa por dia de atraso); transportar para o Brasil pessoa sem documentação regular (multa por pessoa); a transportadora não atender ao compromisso de manutenção ou saída de quem teve ingresso condicional (multa); e furtar-se ao controle migratório (multa).', '["Entrada não autorizada: deportação.","Excesso de permanência: multa por dia e deportação.","Registro em 90 dias: multa.","Registro para residência em 30 dias: multa por dia.","Transportadora: multa por pessoa transportada irregular."]'::jsonb, '["Registro: 90 dias após o ingresso; residência: 30 dias após a orientação."]'::jsonb, 'A companhia aérea que traz passageiro sem documentação regular é multada por pessoa.', '["Assertiva que prevê prisão para a entrada irregular erra: a sanção é a deportação (ou multa)."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-109' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6c322a916a45da2eef036e1899649e9f582d62a3cd655a9d1ca053c7ad5eac9b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
