insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As taxas e emolumentos consulares são fixados conforme a tabela anexa. Os valores poderão ser ajustados pelo órgão competente da administração federal, para preservar o interesse nacional ou assegurar a reciprocidade. Não serão cobrados emolumentos consulares pela concessão de vistos diplomáticos, oficiais e de cortesia, nem de vistos em passaportes diplomáticos, oficiais ou de serviço mediante reciprocidade. Não serão cobrados taxas e emolumentos pela concessão de vistos ou documentos para regularização migratória aos integrantes de grupos vulneráveis e indivíduos em condição de hipossuficiência econômica.', '["Tabela anexa.","Ajuste por interesse nacional ou reciprocidade.","Isenção para vistos especiais.","Isenção para vulneráveis e hipossuficientes."]'::jsonb, '["Isenção para grupos vulneráveis e hipossuficientes."]'::jsonb, 'O migrante sem recursos regulariza a situação sem pagar taxas.', '["Assertiva que cobra taxas dos hipossuficientes na regularização erra."]'::jsonb, '[]'::jsonb, '["Anexo"]'::jsonb, 'under_review', 'claude'
